grid = [[1, 3, 5], [7, 8, 9], [10, 12, 13]]

# 1. A flag
found = None
for r, row in enumerate(grid):
    for c, value in enumerate(row):
        if value % 2 == 0:
            found = (r, c, value)
            break
    if found:
        break
print("flag:", found)

# 2. A function - return exits every loop at once
def first_even(grid):
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value % 2 == 0:
                return (r, c, value)
    return None
print("function:", first_even(grid))

# 3. for-else: break the outer loop only if the inner one broke
for row in grid:
    for value in row:
        if value % 2 == 0:
            break
    else:
        continue
    break
print("for-else:", value)

# 4. Flatten the two loops into one with itertools.product
from itertools import product
for r, c in product(range(3), range(3)):
    if grid[r][c] % 2 == 0:
        print("product:", (r, c, grid[r][c]))
        break

# OUTPUT:
# flag: (1, 1, 8)
# function: (1, 1, 8)
# for-else: 8
# product: (1, 1, 8)

# Limitation: leave BOTH loops by wrapping them in a function
def find(grid, target):
    for r_i, row in enumerate(grid):
        for c_i, v in enumerate(row):
            if v == target:
                return (r_i, c_i)        # exits both loops at once
    return None

print(find([[1, 2], [3, 4]], 3))
print(find([[1, 2], [3, 4]], 9))

# OUTPUT:
# (1, 0)
