def safe_calc(a, op, b):
    try:
        return a / b if op == "/" else {"+": a + b, "-": a - b, "*": a * b}[op]
    except ZeroDivisionError:
        return "cannot divide by zero"
    except KeyError:
        return "unknown operator"

