# Rules enforced in one place keep the state valid
class Account:
    def __init__(self, balance=0):
        self.balance = balance
    def deposit(self, amt):
        if amt <= 0:
            raise ValueError("deposit must be positive")
        self.balance += amt
    def withdraw(self, amt):
        if amt > self.balance:
            raise ValueError("insufficient funds")
        self.balance -= amt

a = Account(100)
a.deposit(50)
try:
    a.withdraw(500)
except ValueError as e:
    print("error:", e)
print(a.balance)

# OUTPUT:
# error: insufficient funds
# 150

class InsufficientFunds(Exception):
    pass


class Account:
    def __init__(self, balance=0):
        self.balance = balance
        self.history = []

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("deposit must be positive")
        self.balance += amount
        self.history.append(("deposit", amount))

    def withdraw(self, amount):
        if amount <= 0 or amount % 100:
            raise ValueError("withdrawal must be a positive multiple of 100")
        if amount > self.balance:
            raise InsufficientFunds(f"balance is only {self.balance}")
        self.balance -= amount
        self.history.append(("withdraw", amount))


acc = Account(5000)
acc.deposit(2500)
acc.withdraw(3000)
print(acc.balance, acc.history)

try:
    acc.withdraw(10_000)
except InsufficientFunds as error:
    print("Error:", error)

# OUTPUT:
# 4500 [('deposit', 2500), ('withdraw', 3000)]
# Error: balance is only 4500

students = {}      # roll number -> {"name": ..., "marks": ...}


def read_marks():
    while True:
        text = input("Marks (0-100): ").strip()
        if text.isdigit() and 0 <= int(text) <= 100:
            return int(text)
        print("Please enter a whole number from 0 to 100.")

def add_student():
    roll = input("Roll number: ").strip()
    if roll in students:
        print("That roll number already exists.")
        return
    name = input("Name: ").strip().title()
    students[roll] = {"name": name, "marks": read_marks()}
    print(f"Added {name}.")


def view_students():
    if not students:
        print("No records yet.")
        return
    print(f"{'Roll':<6}{'Name':<15}{'Marks':>5}")
    print("-" * 26)
    for roll in sorted(students):
        s = students[roll]
        print(f"{roll:<6}{s['name']:<15}{s['marks']:>5}")


def search_students():
    query = input("Name contains: ").strip().lower()
    matches = [(r, s) for r, s in students.items() if query in s["name"].lower()]
    if not matches:
        print("No match found.")
    for roll, s in matches:
        print(f"{roll}: {s['name']} ({s['marks']})")


def update_marks():
    roll = input("Roll number: ").strip()
    if roll not in students:
        print("No such student.")
        return
    students[roll]["marks"] = read_marks()
    print("Marks updated.")


def delete_student():
    roll = input("Roll number: ").strip()
    if roll not in students:
        print("No such student.")
        return
    if input(f"Delete {students[roll]['name']}? (y/n): ").strip().lower() == "y":
        del students[roll]
        print("Deleted.")

