    pass

def withdraw(account, amount):
    if account["locked"]:
        raise AccountLockedError(f"account {account['id']} is locked")
    if amount > account["balance"]:
        raise InsufficientFundsError(f"balance {account['balance']} < {amount}")
    account["balance"] -= amount

