import inspect


def call_chain():
    frame = inspect.currentframe().f_back
    names = []
    while frame is not None:
        names.append(frame.f_code.co_name)
        frame = frame.f_back
    return names


def frame_count():
    return len(call_chain())


def level_one():
    return level_two()


def level_two():
    return call_chain()


def recurse(n):
    if n == 0:
        return frame_count()
    return recurse(n - 1)


def main():
    # Run with: python demo.py (an IDE or runner may add extra outer frames)
    print(level_one())

    extra = recurse(3) - frame_count()
    print("Extra frames for recurse(3):", extra)

    print(inspect.currentframe().f_globals is globals())


if __name__ == "__main__":
    main()

