class LinkedList:
    def __init__(self):
        self.head = None
    def prepend(self, value):                 # O(1): no shifting
        self.head = Node(value, self.head)
    def to_list(self):
        out, cur = [], self.head
        while cur:
            out.append(cur.value)
            cur = cur.next
        return out

