print(balanced("{[(])}"))

# OUTPUT:
# True
# False

def eval_rpn(expr):
    stack = []
    for tok in expr.split():
        if tok in "+-*":
            b, a = stack.pop(), stack.pop()        # right operand is on top
            stack.append(a + b if tok == "+" else a - b if tok == "-" else a * b)
        else:
            stack.append(int(tok))
    return stack[0]

