def in_range(n, lo, hi):
    if n is None: return []
    out = []
    if lo < n.val: out += in_range(n.left, lo, hi)     # left only if it can hold values >= lo
    if lo <= n.val <= hi: out.append(n.val)
    if n.val < hi: out += in_range(n.right, lo, hi)    # right only if it can hold values <= hi
    return out

