def suggest(trie, prefix):
    node = trie
    for ch in prefix:
        if ch not in node:
            return []
        node = node[ch]
    out, stack = [], [(node, prefix)]
    while stack:
        n, p = stack.pop()
        if "#" in n:
            out.append(p)
        for ch, child in n.items():
            if ch != "#":
                stack.append((child, p + ch))
    return sorted(out)

