def bfs(start):
    seen, order, q = {start}, [], deque([start])
    while q:
        n = q.popleft()                  # oldest first (queue)
        order.append(n)
        for nb in graph[n]:
            if nb not in seen:
                seen.add(nb); q.append(nb)
    return order

def dfs(n, seen=None, order=None):
    seen = set() if seen is None else seen
    order = [] if order is None else order
    seen.add(n); order.append(n)
    for nb in graph[n]:
        if nb not in seen:
            dfs(nb, seen, order)         # go deep first
    return order

print("BFS:", bfs("A"))
print("DFS:", dfs("A"))

# OUTPUT:
# BFS: ['A', 'B', 'C', 'D', 'E', 'F']
# DFS: ['A', 'B', 'D', 'E', 'F', 'C']

from collections import deque

graph = {"A": ["B", "C"], "B": ["D", "E"], "C": ["F"], "D": [], "E": ["F"], "F": []}

def shortest_path(start, goal):
    parent, q = {start: None}, deque([start])
    while q:
        n = q.popleft()
        if n == goal:
            path = []
            while n is not None:         # walk parents back to the start
                path.append(n); n = parent[n]
            return path[::-1]
        for nb in graph[n]:
            if nb not in parent:
                parent[nb] = n; q.append(nb)

print(shortest_path("A", "F"))

# OUTPUT:
# ['A', 'C', 'F']

graph = {"A": ["B", "C"], "B": ["D", "E"], "C": ["F"], "D": [], "E": ["F"], "F": []}

def dfs_path(n, goal, seen=()):
    if n == goal:
        return [n]
    for nb in graph[n]:
        if nb not in seen:
            p = dfs_path(nb, goal, seen + (n,))
            if p:
                return [n] + p
    return None

