import heapq

graph = {"A": [("B", 1), ("C", 4)], "B": [("C", 2), ("D", 5)], "C": [("D", 1)], "D": []}

def dijkstra(src):
    dist = {n: float("inf") for n in graph}
    dist[src] = 0
    heap = [(0, src)]
    while heap:
        d, n = heapq.heappop(heap)
        if d > dist[n]:
            continue                       # stale entry: a better route was found
        for nb, w in graph[n]:
            if d + w < dist[nb]:
                dist[nb] = d + w
                heapq.heappush(heap, (dist[nb], nb))
    return dist

