from functools import wraps
def require_role(role):
    def deco(fn):
        @wraps(fn)
        def inner(user, *a, **k):
            if user.get("role") != role:
                raise PermissionError(f"needs {role}")
            return fn(user, *a, **k)
        return inner
    return deco

@require_role("admin")
def delete_user(user, uid): return f"deleted {uid}"
print(delete_user({"name": "ada", "role": "admin"}, 7))

