import json

def run_tool_call(call, registry):
    """Execute one model-requested call and build the tool message for the next turn."""
    fn = registry[call["name"]]
    result = fn(**json.loads(call["arguments"]))
    return {"role": "tool", "tool_call_id": call["id"], "content": json.dumps(result)}

reg = {"add": lambda a, b: a + b}
print(run_tool_call({"id": "c1", "name": "add", "arguments": '{"a": 2, "b": 3}'}, reg))

# OUTPUT:
# {'role': 'tool', 'tool_call_id': 'c1', 'content': '5'}

ALLOWED = {"get_weather", "add"}

def safe_dispatch(name, args, registry):
    if name not in ALLOWED:                      # never exec arbitrary names
        return {"error": f"unknown tool {name}"}
    return registry[name](**args)

print(safe_dispatch("delete_all_files", {}, {}))

# OUTPUT:
# {'error': 'unknown tool delete_all_files'}

# The core agent loop, with a scripted "model" so the control flow is visible
def fake_llm(history):
    """Pretend model: first asks for a tool, then answers using the result."""
    if not any(m["role"] == "tool" for m in history):
        return {"tool": "add", "args": {"a": 2, "b": 3}}
    return {"final": "The sum is 5."}

tools = {"add": lambda a, b: a + b}
history = [{"role": "user", "content": "What is 2 + 3?"}]
for step in range(5):                                   # hard step limit
    out = fake_llm(history)
    if "final" in out:
        print(out["final"]); break
    result = tools[out["tool"]](**out["args"])          # act
    history.append({"role": "tool", "content": str(result)})   # observe

# OUTPUT:
# The sum is 5.

# Fallback chain: try the best model, degrade gracefully
def primary(q):  raise TimeoutError("slow")
def backup(q):   return "backup model answer"
def canned(q):   return "Sorry, try again later."

def answer(q):
    for fn in (primary, backup, canned):
        try:
            return fn(q)
        except Exception:
            continue

print(answer("hi"))

