# Two-sum: find a pair that adds to target
def two_sum_slow(nums, t):                 # O(n^2): check every pair
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == t:
                return (i, j)

def two_sum_fast(nums, t):                 # O(n): remember what we have seen
    seen = {}
    for i, x in enumerate(nums):
        if t - x in seen:
            return (seen[t - x], i)
        seen[x] = i

nums = [2, 7, 11, 15]
print(two_sum_slow(nums, 9), two_sum_fast(nums, 9))

# OUTPUT:
# (0, 1) (0, 1)

from functools import lru_cache

@lru_cache(maxsize=None)            # same as functools.cache
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

